<?php require __DIR__.'/app/bootstrap.php';require __DIR__.'/app/notifications.php';$error='';$items=cart_items();$key=$_SESSION['checkout_key']??=bin2hex(random_bytes(32));
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['checkout_action']??'')==='coupon'){
 check_csrf();try{submission_limit('coupons',30);$code=substr((string)($_POST['coupon']??''),0,40);coupon_quote($code,cart_subtotal($items));$_SESSION['coupon']=strtoupper(trim($code));}catch(DomainException $e){$error=$e->getMessage();}
}elseif($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$postedKey=(string)($_POST['checkout_key']??'');
 if(!hash_equals($key,$postedKey))$error='Checkout has changed. Refresh and try again.';
 else{
 $name=trim((string)($_POST['name']??''));$phone=preg_replace('/[\s-]/','',(string)($_POST['phone']??''));$email='';$address=trim((string)($_POST['address']??''));$area='To be confirmed';$notes='';
 if(strlen($name)<2||strlen($name)>120||!preg_match('/^(?:\+?88)?01[3-9]\d{8}$/',$phone)||strlen($address)<10||strlen($address)>1500||empty($_POST['agree']))$error='Please enter a valid name, Bangladesh phone number, delivery address, and accept the order terms.';
 else{try{db()->beginTransaction();
   $existing=query('SELECT access_token FROM orders WHERE checkout_key=?',[$key])->fetch();
   if($existing){db()->commit();redirect('order.php?token='.$existing['access_token']);}
   $items=cart_items(true);if(!$items||count($items)!==count($_SESSION['cart']??[]))throw new DomainException('Your bag contains an unavailable item. Return to the bag and update it.');
   foreach($items as $p)if($p['stock']!==null&&$p['qty']>(int)$p['stock'])throw new DomainException($p['name'].' in '.$p['size'].' no longer has that quantity available.');
   $subtotal=cart_subtotal($items);$fee=hoodie_free_delivery($items)?0:null;$fee=$fee===null||$fee===''?null:(int)$fee;$discount=coupon_quote((string)($_SESSION['coupon']??''),$subtotal,true);$total=$fee===null?null:$subtotal-$discount['amount']+$fee;
   $token=bin2hex(random_bytes(32));$reference='FL-'.strtoupper(bin2hex(random_bytes(5)));
   query('INSERT INTO orders(reference,access_token,checkout_key,customer_name,phone,email,address,area,notes,subtotal,delivery_fee,total) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$reference,$token,$key,$name,$phone,$email,$address,$area,$notes,$subtotal,$fee,$total]);$orderId=db()->lastInsertId();
   if($discount['id']){query('UPDATE coupons SET uses=uses+1 WHERE id=?',[$discount['id']]);query('INSERT INTO order_discounts(order_id,coupon_id,code,amount) VALUES(?,?,?,?)',[$orderId,$discount['id'],$discount['code'],$discount['amount']]);}
   foreach($items as $p){query('INSERT INTO order_items(order_id,product_id,product_name,size,unit_price,quantity,stock_reserved) VALUES(?,?,?,?,?,?,?)',[$orderId,$p['id'],$p['name'],$p['size'],$p['price'],$p['qty'],$p['stock']===null?0:1]);if($p['stock']!==null)query('UPDATE variants SET stock=stock-? WHERE product_id=? AND size=?',[$p['qty'],$p['id'],$p['size']]);}
   notification_enqueue((int)$orderId);db()->commit();notification_try((int)$orderId);$_SESSION['cart']=[];unset($_SESSION['coupon']);$_SESSION['last_order']=$token;redirect('order.php?token='.$token);
 }catch(DomainException $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}catch(PDOException $e){if(db()->inTransaction())db()->rollBack();if($e->getCode()==='23000'){$existing=query('SELECT access_token FROM orders WHERE checkout_key=?',[$key])->fetch();if($existing)redirect('order.php?token='.$existing['access_token']);}throw $e;}}
 }
}
if(!$items){if(!empty($_SESSION['last_order']))redirect('order.php?token='.$_SESSION['last_order']);redirect('cart.php');}
$discount=['amount'=>0,'code'=>''];try{$discount=coupon_quote((string)($_SESSION['coupon']??''),cart_subtotal($items));}catch(DomainException $e){unset($_SESSION['coupon']);if(!$error)$error=$e->getMessage();}
$freeDelivery=hoodie_free_delivery($items);render_header('Checkout'); ?>
<main class="page"><p class="eyebrow">ONE STEP CLOSER</p><h1>Checkout.</h1><?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif ?><form method="post" class="checkout-layout" id="checkout-form"><?=csrf_input()?><input type="hidden" name="checkout_key" value="<?=h($key)?>"><section><h2>Delivery details</h2><div class="form-grid"><label>Full name<input name="name" required maxlength="120" autocomplete="name" value="<?=h($_POST['name']??'')?>"></label><label>Phone number<input name="phone" type="tel" required maxlength="20" autocomplete="tel" placeholder="01XXXXXXXXX" value="<?=h($_POST['phone']??'')?>"></label></div><label>Delivery address<textarea name="address" required minlength="10" maxlength="1500" autocomplete="street-address" placeholder="House, road, area, district and postcode"><?=h($_POST['address']??'')?></textarea></label><p class="hint">Estimated delivery: inside Dhaka <?=h(setting('delivery_estimate_dhaka'))?>; outside Dhaka <?=h(setting('delivery_estimate_outside'))?>.</p><h2 class="spaced">Payment</h2><div class="payment-option"><strong>Cash on delivery</strong><p>Pay when your order arrives. The team will confirm your order before dispatch.</p></div><label class="check-label"><input type="checkbox" name="agree" value="1" required <?=isset($_POST['agree'])?'checked':''?>><span>I agree to the <a href="<?=url('info.php?page=terms')?>" target="_blank" rel="noopener">Terms & Conditions</a> and <a href="<?=url('info.php?page=returns')?>" target="_blank" rel="noopener">Refund, Trial & Exchange Policy</a>, and have read the <a href="<?=url('info.php?page=privacy')?>" target="_blank" rel="noopener">Privacy Policy</a>. If delivery fees are pending, the team must confirm them with me before dispatch.</span></label></section>
<aside class="summary-box"><h2>Your order</h2><label>Discount code<input name="coupon" maxlength="40" value="<?=h($discount['code'])?>" autocomplete="off"></label><button class="button outline" name="checkout_action" value="coupon" formnovalidate>APPLY / CLEAR CODE</button><p class="hint">Leave the code blank and apply to remove it. One code per order; delivery is not discounted.</p><?php foreach($items as $p):?><div class="summary-line"><span><?=h($p['name'])?> / <?=h($p['size'])?> × <?=$p['qty']?></span><strong><?=money($p['price']*$p['qty'])?></strong></div><?php endforeach ?><div class="summary-line"><span>Subtotal</span><strong id="checkout-subtotal" data-subtotal="<?=cart_subtotal($items)-$discount['amount']?>"><?=money(cart_subtotal($items))?></strong></div><?php if($discount['amount']):?><div class="summary-line"><span>Discount · <?=h($discount['code'])?></span><strong>−<?=money($discount['amount'])?></strong></div><?php endif ?><div class="summary-line"><span>Delivery</span><strong id="delivery-amount"><?=$freeDelivery?'FREE':'To be confirmed'?></strong></div><div class="summary-line total"><span>Total</span><strong id="checkout-total"><?=$freeDelivery?money(cart_subtotal($items)-$discount['amount']):'Pending delivery fee'?></strong></div><p id="delivery-note"><?=$freeDelivery?'Free delivery applied: your bag contains 2 or more hoodies.':'We will confirm the delivery charge with you by phone before dispatch.'?></p><button class="button dark" id="place-order">ORDER NOW ↗</button><p class="hint">No online payment is taken. You’ll receive an order reference on the next screen.</p></aside></form></main><?php render_footer(); ?>
